// FUNCTION: BFME2 0x0010657E size=91 name=?getWidth@W3DDisplayString@@UAEHH@Z evidence=N:ledger tier=B hypothesis:cohesion
int W3DDisplayString::getWidth(int charPos)
{
	int width = 0;
	int count = 0;

	FontCharsClass *font = m_textRenderer.m_font;
	if (font)
	{
		const unsigned short *text = m_textString.str();
		unsigned short ch;
		while ((ch = *text++) != 0 && (charPos == -1 || count < charPos))
		{
			if (ch != 0x0A)
				width += font->Get_Char_Spacing(ch);
			count++;
		}
	}

	return width;
}

// FUNCTION: BFME2 0x001065D9 size=138 name=?computeExtents@W3DDisplayString@@IAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void W3DDisplayString::computeExtents()
{
	unsigned int len = getTextLength();
	if (len == 0 || m_font == 0)
	{
		m_width = 0;
		m_height = 0;
	}
	else
	{
		Vector2 extents = m_textRenderer.Get_Formatted_Text_Extents(getText().str());
		m_width = (int)extents.X;
		m_height = (int)extents.Y;
	}
}

// FUNCTION: BFME2 0x00106663 size=80 name=?notifyTextChanged@W3DDisplayString@@UAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void W3DDisplayString::notifyTextChanged()
{
	if (TheGlobalLanguageData)
	{
		if (TheGlobalLanguageData->m_useHardWordWrap == true)
		{
			m_textRenderer.m_useHardWordWrap = true;
			m_hotKeyRenderer.m_useHardWordWrap = true;
		}
		else
		{
			m_textRenderer.m_useHardWordWrap = false;
			m_hotKeyRenderer.m_useHardWordWrap = false;
		}
	}
	computeExtents();
	m_textChanged = true;
	m_textRenderer.Reset();
	m_hotKeyRenderer.Reset();
}

// FUNCTION: BFME2 0x001066B3 size=88 name=?setFont@W3DDisplayString@@UAEXPAVGameFont@@@Z evidence=N:ledger tier=B hypothesis:cohesion
void W3DDisplayString::setFont(GameFont *font)
{
	if (font != 0 && m_font != font)
	{
		m_font = font;
		m_textRenderer.Set_Font((FontCharsClass *)font->fontData);
		GameFont *boldFont = TheFontLibrary->getFont(&font->nameString, font->pointSize, true);
		m_hotKeyRenderer.Set_Font((FontCharsClass *)boldFont->fontData);
		computeExtents();
		m_fontChanged = true;
	}
}

